    <script type="text/javascript">
        Sys.WebForms.PageRequestManager.getInstance().add_pageLoaded(function () {
            var canSave = false;
            $('#divInSubType').css('display', 'none');
            $('.tdSpecify').css('display', 'none');
            $('#aRail').css('display', 'none');

            $("#rbtInSubType").attr('selectedIndex', '-1');
            if ($('#hdnUserType').val() == "TR") {
                $('#txtConsignor').addClass("required");
                $('#slToState').addClass("required");
                $('.txtToGSTIN').addClass("required");
                $('#txtToAddr1').addClass("required");
                $('.txtToPlace').addClass("required");
                $('.txtToPincode').addClass("required");
            }
            $('#ctl00_ContentPlaceHolder1_rbtOutwardInward input').on('click', function (e) {

                var enableChange = true;

                $('.tdSpecify').css('display', 'none');
                if ($.trim($("#hdnUserType").val()) == "TRN" || $.trim($("#hdnUserType").val()) == "CTZ") {
                    enableChange = false;
                }
                $('#tblProducts tr').each(function (row, tr) {
                    if ($(tr).find('td:eq(2) input').val() !== undefined && $(tr).find('td:eq(2) input').val() != "") {
                        enableChange = false;
                        e.preventDefault();
                        $.alert("Supply type cannot be changed as the products have been entered. However, you can delete all the products and then change the Supply type");
                        $(this).prop("checked", false);
                        return false;
                    }
                });


                if (enableChange) {
                    $.ajax({

                        type: "POST",
                        contentType: "application/json; charset=utf-8",
                        url: "../eway-simulation/get-default-gstin",
                        dataType: "json",
                        beforeSend: function (xhr) {
                            xhr.setRequestHeader("STicket", $("#mytoken").val());
                        },
                        success: function (data) {

                            if ($('#ctl00_ContentPlaceHolder1_rbtOutwardInward input:checked').val() == "O") {
                                if (data.d.tradeName == null || (data.d.tradeName != null &&
                                    data.d.tradeName.trim() == String.Empty)) {
                                    if (data.d.legalName != null)
                                        $(".txtFromTrdName").val(data.d.legalName);
                                }
                                else {

                                    if (data.d.tradeName != null)
                                        $(".txtFromTrdName").val(data.d.tradeName);
                                }
                                if (data.d.gstin != null)
                                    $(".txtFromGSTIN").val(data.d.gstin);
                                if (data.d.addr1 != null)
                                    $(".txtFromAddr1").val(data.d.addr1);
                                if (data.d.addr2 != null)
                                    $(".txtFromAddr2").val(data.d.addr2);
                                if (data.d.addrplace != null)
                                    $(".txtFromPlace").val(data.d.addrplace);
                                if (data.d.pincode != null)
                                    $(".txtFromPincode").val(data.d.pincode);
                                if (data.d.stateCode != null) {
                                    if (data.d.isSez == "Y") {
                                        $('#hdnfrmSez').val('Y');
                                        $("#slFromState").val('99');
                                    }
                                    else {
                                        $('#hdnfrmSez').val('N');
                                        $("#slFromState").val(data.d.stateCode);
                                    }
                                    $("#slFromStateAct").val(data.d.stateCode);
                                    //$("#slFromState").prop("disabled", true);
                                }

                                if (data.d.gstin != null)
                                    $('#hdnFromId').val(data.d.gstin);

                                $("#hdnFromType").val($('#hdnUserType').val());
                                if ($("#hdnUserType").val() == "TXP") {
                                    if (data.d.gstin.length >= 2)
                                        $(".txtFromGSTIN").prop("readonly", true);
                                }

                                $(".txtToTrdName").prop("readonly", false);
                                $(".txtToGSTIN").prop("readonly", false);
                                $("#slToState").prop("disabled", false);
                                $(".txtToTrdName").val('');
                                $(".txtToGSTIN").val('');
                                $(".txtToAddr1").val('');
                                $(".txtToAddr2").val('');
                                $(".txtToPlace").val('');
                                $(".txtToPincode").val('');
                                $("#slToState").val('0');
                                $("#slToStateAct").val('0');
                                $('#hdnToId').val('');
                                $("#hdnToType").val('');
                            }
                            else {
                                $(".txtFromTrdName").val('');
                                $(".txtFromGSTIN").val('');
                                $(".txtFromAddr1").val('');
                                $(".txtFromAddr2").val('');
                                $(".txtFromPlace").val('');
                                $(".txtFromPincode").val('');
                                $("#slFromState").val('0');
                                $("#slFromStateAct").val('0');
                                $('#hdnFromId').val('');
                                $("#hdnFromType").val('');
                                $('#hdnfrmSez').val('N');
                                $(".txtFromTrdName").prop("readonly", false);
                                $(".txtFromGSTIN").prop("readonly", false);
                                $("#slFromState").prop("disabled", false);

                                if ($("#hdnUserType").val() == "TXP") {
                                    if (data.d.gstin.length >= 2)
                                        $(".txtToGSTIN").prop("readonly", true);
                                }
                                $(".txtToTrdName").val(data.d.name);
                                if (data.d.gstin != null)
                                    $(".txtToGSTIN").val(data.d.gstin);
                                if (data.d.addr1 != null)
                                    $(".txtToAddr1").val(data.d.addr1)
                                if (data.d.addr2 != null)
                                    $(".txtToAddr2").val(data.d.addr2);
                                if (data.d.addrplace != null)
                                    $(".txtToPlace").val(data.d.addrplace);
                                if (data.d.pincode != null)
                                    $(".txtToPincode").val(data.d.pincode);
                                if (data.d.stateCode != null) {
                                    if (data.d.isSez == "Y") { $('#hdntoSez').val('Y'); $("#slToState").val('99'); }
                                    else {
                                        $('#hdntoSez').val('N');
                                        $("#slToState").val(data.d.stateCode);
                                    }
                                    //$("#slToState").prop("disabled", true);
                                    $("#slToStateAct").val(data.d.stateCode);
                                }
                                if (data.d.gstin != null)
                                    $('#hdnToId').val(data.d.gstin);
                                $("#hdnToType").val($('#hdnUserType').val());
                            }
                        }
                    });
                    }

                if ($('#ctl00_ContentPlaceHolder1_rbtOutwardInward input:checked').val() == "O") {
                    $('#divOutSubType').css('display', 'block');
                    $('#divInSubType').css('display', 'none');
                    $('#ctl00_ContentPlaceHolder1_rbtInSubType input[type=radio]').prop('checked', false);

                }
                else {
                    $('#divOutSubType').css('display', 'none');
                    $('#divInSubType').css('display', 'block');
                    $(".rbtOutSubType").attr('selectedIndex', '-1');
                    $('#ctl00_ContentPlaceHolder1_rbtOutSubType input[type=radio]').prop('checked', false);
                }
            });
            $('#ctl00_ContentPlaceHolder1_rbtOutSubType input').on('click', function (e) {
                var cnt = 0; $('#tblProducts tr').each(function (row, tr) {
                    if ($(tr).find('td:eq(2) input').val() !== undefined && $(tr).find('td:eq(2) input').val() != "") {
                        enableChange = false;
                        cnt = 1;
                        e.preventDefault();
                        $.alert("Sub type cannot be changed as the products have been entered. However, you can delete all the products and then change the Sub type");
                        $(this).prop("checked", false);
                        return false;
                    }
                });
                if (cnt == 0) {
                    EnableDocsType($('#ctl00_ContentPlaceHolder1_rbtOutwardInward input:checked').val(), $('#ctl00_ContentPlaceHolder1_rbtOutSubType input:checked').val());
                    if ($('#ctl00_ContentPlaceHolder1_rbtOutSubType input:checked').val() == "8") {
                        $('.tdSpecify').css('display', 'block');
                    }
                    else {
                        $('.tdSpecify').css('display', 'none');
                    }
                }
            });

            $('#ctl00_ContentPlaceHolder1_rbtInSubType input').on('click', function (e) {
                var cnt = 0;
                $('#tblProducts tr').each(function (row, tr) {
                    if ($(tr).find('td:eq(2) input').val() !== undefined && $(tr).find('td:eq(2) input').val() != "") {
                        enableChange = false;
                        cnt = 1;
                        e.preventDefault();
                        $.alert("Sub type cannot be changed as the products have been entered. However, you can delete all the products and then change the Sub type");
                        $(this).prop("checked", false);
                        return false;
                    }
                });
                if (cnt == 0) {
                    EnableDocsType($('#ctl00_ContentPlaceHolder1_rbtOutwardInward input:checked').val(), $('#ctl00_ContentPlaceHolder1_rbtInSubType input:checked').val());
                    if ($('#ctl00_ContentPlaceHolder1_rbtInSubType input:checked').val() == "8") {
                        $('.tdSpecify').css('display', 'block');
                    }
                    else {

                        $('.tdSpecify').css('display', 'none');
                    }
                }
            });

            $("#txtTransporter").autocomplete({
                source: function (request, response) {
                    var tranName = $.trim($("#txtTransporter").val().toLowerCase());
                    $.ajax({
                        type: "POST",
                        contentType: "application/json; charset=utf-8",
                        url: "../eway-simulation/get-matched-transport-names",
                        data: "{'nameStr':'" + tranName + "'}",
                        dataType: "json",
                        beforeSend: function (xhr) {
                            xhr.setRequestHeader("STicket", $("#mytoken").val());

                        },
                        dataFilter: function (data) { return data; },
                        success: function (data) {
                            $(".txtTransid").val(data.d[0].transId);
                            $(".txtTransporter").val(data.d[0].transName);
                        }
                    });
                },
                select: function (event, ui) {
                    if (ui.item) {
                        alert("1");
                        $(".txtTransid").val(ui.item.transid);
                    }
                },
                minLength: 2
            });

            $(".txtFromTrdName").autocomplete({
                source: function (request, response) {

                    var nmval = $.trim($(".txtFromTrdName").val().toLowerCase());

                    var hdn = $("#hdn_uunqid").val();
                    if ($('#ctl00_ContentPlaceHolder1_rbtOutwardInward input:checked').val() == "O") {
                        $.ajax({
                            type: "POST",
                            contentType: "application/json; charset=utf-8",
                            url: "../BillGeneration/BillGeneration.aspx/GetMatchedAddlPlaceNames",
                            data: "{'nameStr':'" + nmval + "','userGstin':'" + $("#hdnUserGstin").val() + "'}",
                            dataType: "json",
                            beforeSend: function (xhr) {
                                xhr.setRequestHeader("STicket", $("#mytoken").val());
                            },
                            dataFilter: function (data) { return data; },
                            success: function (data) {

                                response($.map(data.d, function (item) {
                                    return {
                                        value: item.name + ', ' + item.addrplace, addrs1: item.addr1, addrs2: item.addr2, addrplace: item.addrplace,
                                        clientid: item.clientId, state: item.stateCode, gstin: item.gstin,
                                        pincode: item.pincode
                                    }
                                }))
                            }
                        });
                    }
                    else {
                        $.ajax({

                            type: "POST",
                            contentType: "application/json; charset=utf-8",
                            url: "../BillGeneration/BillGeneration.aspx/GetMatchedSupplierNames",
                            data: "{'nameStr':'" + nmval + "','userGstin':'" + $("#hdnUserGstin").val() + "'}",
                            dataType: "json",
                            beforeSend: function (xhr) {
                                xhr.setRequestHeader("STicket", $("#mytoken").val());

                            },
                            dataFilter: function (data) { return data; },
                            success: function (data) {

                                response($.map(data.d, function (item) {
                                    return {
                                        value: item.supplierName + ', ' + item.supplierBusPlace, addrs1: item.supplierBusAddr1,
                                        addrs2: item.supplierBusAddr2, addrplace: item.supplierBusPlace,
                                        clientid: item.supplierGstin_eid, state: item.supplierStateCode, gstin: item.supplierGstin,
                                        pincode: item.supplierBusPincode, distance: item.approxDistance

                                    }
                                }))
                            }

                        });
                    }
                },
                select: function (event, ui) {

                    if (ui.item) {
                        $(".txtFromGSTIN").val(ui.item.gstin);
                        $(".txtFromAddr1").val(ui.item.addrs1);
                        $(".txtFromAddr2").val(ui.item.addrs2);
                        $(".txtFromPlace").val(ui.item.addrplace);
                        $(".txtFromPincode").val(ui.item.pincode);
                        $("#slFromState").val(ui.item.state);
                        $("#slFromStateAct").val(ui.item.state);
                        //$("#slFromState").prop("disabled", true);
                        if ($.trim($(".txtFromGSTIN").val()).length == 15) {
                            $(".txtFromGSTIN").prop("readonly", true);
                        }
                        $('#hdnFromId').val(ui.item.gstin);
                        $(".txtDistance").val(ui.item.distance);
                        if ($('#HeadTable .slFromState option:selected').val() != '0' && $('#HeadTable .slToState option:selected').val() != '0'
                                                   && $('#HeadTable .slFromState option:selected').val() != $('#HeadTable .slToState option:selected').val()) {
                            $("#txtCGST").prop("readonly", true);
                            $("#txtSGST").prop("readonly", true);
                        }
                        else {
                            $("#txtCGST").prop("readonly", false);
                            $("#txtSGST").prop("readonly", false);

                        }
                        if ($('#HeadTable .slFromState option:selected').val() != '0' && $('#HeadTable .slToState option:selected').val() != '0'
                                    && $('#HeadTable .slFromState option:selected').val() == $('#HeadTable .slToState option:selected').val()) {
                            $("#txtIGST").prop("readonly", true);
                        }
                        else {
                            $("#txtIGST").prop("readonly", false);
                        }
                    }
                },
                minLength: 2
            });

            $(".txtToTrdName").autocomplete({

                source: function (request, response) {

                    var nmval = $.trim($(".txtToTrdName").val().toLowerCase());
                    if ($("#hdnDist").val() == '')
                    { GetDistance(); }
                    var hdn = $("#hdn_uunqid").val();
                    if ($('#ctl00_ContentPlaceHolder1_rbtOutwardInward input:checked').val() == "O") {

                        $.ajax({
                            type: "POST",
                            contentType: "application/json; charset=utf-8",
                            url: "../eway-simulation/get-matched-client-names",
                            data: "{'nameStr':'" + nmval + "','userGstin':'" + $("#hdnUserGstin").val() + "'}",
                            dataType: "json",
                            beforeSend: function (xhr) {
                                xhr.setRequestHeader("STicket", $("#mytoken").val());
                            },
                            dataFilter: function (data) { return data; },
                            success: function (data) {

