                        objinv.subSupplyType = $('#ctl00_ContentPlaceHolder1_rbtOutSubType input:checked').val();
                    else
                        objinv.subSupplyType = $('#ctl00_ContentPlaceHolder1_rbtInSubType input:checked').val();
                    if (objinv.subSupplyType == null) {
                        $.alert("Please select Supply subtype");
                        $('#btnsbmt').prop('disabled', false);
                        return false;
                    }
                    objinv.subSupplyDesc = $("#txtSpecify").val();
                    if (objinv.subSupplyType == "8" && (objinv.subSupplyDesc == null || objinv.subSupplyDesc.trim() == "")) {
                        $.alert("Please Specify Other Sub Type");
                        $('#btnsbmt').prop('disabled', false);
                        return false;
                    }
                    if ($('.txtDistance').val() == '' || ($.trim($('.txtDistance').val()) != '' && parseInt($('.txtDistance').val()) <= 0)) {

                        $.alert("Please enter the distance in transporter section.");
                        $('#btnsbmt').prop('disabled', false);
                        return false;

                    }
                    if ($.trim($('.txtDistance').val()) != '' && parseInt($('.txtDistance').val()) > 4000) {

                        $.alert("Distance cannot be more than 4000Km, Please enter accordingly.");
                        $('#btnsbmt').prop('disabled', false);
                        return false;

                    }
                    if ($.trim($('.txtTransid').val()) == '' && $('#HeadTable .rblMode input:checked').val() == "1" && $('#hdnIsallgold').val() != "Y") {
                        if ($.trim($(".txtVehicleNo").val()) == '') {
                            $.alert("Enter Part-B Details or Transporter Information")
                            $('#btnsbmt').prop('disabled', false);
                            return false;
                        }

                    }
                    if ($.trim($('.txtTransid').val()) != '' && $.trim($('.txtTransid').val()).length != 15) {
                        $.alert("Invalid Transporter ID");
                        $('#btnsbmt').prop('disabled', false);
                        return false;
                    }
                    if ($('#HeadTable .rblMode input:checked').val() == "2" || $('#HeadTable .rblMode input:checked').val() == "3") {
                        if ($.trim($(".txtTransDocNo").val()) == '') {
                            if ($('#HeadTable .rblMode input:checked').val() == "2") {
                                $.alert("Please enter RR No.");
                            }
                            else if ($('#HeadTable .rblMode input:checked').val() == "3") {
                                $.alert("Please enter Air Bill No.");
                            }
                            else {
                                $.alert("Please enter Bill of lading No.");
                            }
                            $('#btnsbmt').prop('disabled', false);
                            return false;
                        }
                    }
                    if ($.trim($('.txtTransid').val()) == '' && $('#HeadTable .rblMode input:checked').val() == "4" &&
                       $.trim($(".txtVehicleNo").val()) == '' && $.trim($(".txtTransDocNo").val()) == '') {
                        $.alert("Please enter Transporter ID/ Bill of lading No./Vehicle No.");
                        $('#btnsbmt').prop('disabled', false);
                        return false;
                    }
                    if (!gstrCheck) {
                        var isConfirm = confirm('Alert! Some of the fields mandatory for GSTR1 is not filled! Do you want to continue without them');
                        if (!isConfirm) {
                            $('#btnsbmt').prop('disabled', false);
                            return false;
                        }
                    }
                    if ($('#HeadTable .slFromStateAct option:selected').val() == '97') {
                        $(".txtFromPincode").val('999999');
                    }
                    if ($('#HeadTable .slFromStateAct option:selected').val() != '97' && $('#HeadTable .slFromStateAct option:selected').val() != '0') {
                        if ($(".txtFromPincode").val() == '999999') {
                            $(".txtFromPincode").val('');
                            $.alert("Pls. enter Pincode(From Section)");
                            $('#btnsbmt').prop('disabled', false);
                            return false;
                        }
                    }

                    if ($('#HeadTable .slToStateAct option:selected').val() == '97') {
                        $(".txtToPincode").val('999999');
                    }
                    if ($('#HeadTable .slToStateAct option:selected').val() != '97' &&
                        $('#HeadTable .slToStateAct option:selected').val() != '0') {
                        if ($(".txtToPincode").val() == '999999') {
                            $(".txtToPincode").val('');
                            $.alert("Pls. enter Pincode(To Section)");
                            $('#btnsbmt').prop('disabled', false);
                            return false;
                        }
                    }
                    if ($('#HeadTable .slToStateAct option:selected').val() == "0") {
                        $.alert("Pls. Select Ship to State");
                        $('#btnsbmt').prop('disabled', false);
                        return false;
                    }
                    if ($('#HeadTable .slFromStateAct option:selected').val() == "0") {
                        $.alert("Pls. Select Dispatch State");
                        $('#btnsbmt').prop('disabled', false);
                        return false;
                    }
                    if ($('#HeadTable .ddlDocType option:selected').val() == "0") {
                        $.alert("Pls. Select Document Type");
                        $('#btnsbmt').prop('disabled', false);
                        return false;
                    }
                    if (parseFloat($("#txtTotInvVal").val()) < 0) {
                        $.alert("Total Inv.Val Should not be lesser than 0");
                        $('#btnsbmt').prop('disabled', false);
                        return false;
                    }
                    if ($('#HeadTable .slToState option:selected').val() == "99" && $('#hdntoSez').val() != "Y" && objinv.subSupplyType != "3") {
                        $.alert("To State Shouldn't be Other Country");
                        $('#btnsbmt').prop('disabled', false);
                        return false;
                    }
                    if ($('#HeadTable .slFromState option:selected').val() == "99" && $('#hdnfrmSez').val() != "Y" && objinv.subSupplyType != "2") {
                        $.alert("From State Shouldn't be Other Country");
                        $('#btnsbmt').prop('disabled', false);
                        return false;
                    }
                    if ($.trim($('#txtOth').val()) != '' && $.trim($('#txtOth').val()) != "0" && !parseFloat($("#txtOth").val())) {
                        $.alert("Other Value is not Valid");
                        $('#btnsbmt').prop('disabled', false);
                        return false;
                    }
                    if (!parseFloat($("#txtTotInvVal").val())) {
                        if (parseFloat($("#txtTotInvVal").val()) != 0) {
                            $.alert("Total Inv.Value is not Valid");
                            $('#btnsbmt').prop('disabled', false);
                            return false;
                        }
                    }
                    if (!parseInt($(".txtFromPincode").val())) {
                        $.alert("Invalid From Pincode");
                        $('#btnsbmt').prop('disabled', false);
                        return false;
                    }
                    if (!parseInt($(".txtToPincode").val())) {
                        $.alert("Invalid To Pincode");
                        $('#btnsbmt').prop('disabled', false);
                        return false;
                    }
                    var x = document.getElementById("slFromStateAct").disabled;
                    var y = document.getElementById("slToStateAct").disabled;
                    if (!x) {
                        $.alert("Alert..Dispatch From PIN code does not exist. Pls check again");
                    }
                    if (!y) {
                        $.alert("Alert..Ship To PIN code does not exist. Pls check again");
                    }
                    objinv.docType = $('#HeadTable .ddlDocType option:selected').val();
                    objinv.transType = $('#HeadTable .ddlTransType option:selected').val();
                    objinv.docNo = $("#txtDocNo").val();
                    objinv.docDate = $("#txtDocDate").val();
                    objinv.userGstin = $("#hdnUserGstin").val();
                    objinv.userType = $("#hdnUserType").val();
                    objinv.userId = $("#hdnUserLoginName").val();
                    objinv.genMode = "WEB";
                    objinv.fromType = fromType;
                    objinv.fromGstin = $(".txtFromGSTIN").val()
                    objinv.fromAddr1 = $("#txtFromAddr1").val();
                    objinv.fromAddr2 = $("#txtFromAddr2").val();
                    objinv.fromPlace = $(".txtFromPlace").val();
                    objinv.fromPincode = $(".txtFromPincode").val();
                    objinv.fromTrdName = $.trim($(".txtFromTrdName").val());
                    objinv.fromStateCode = $('#HeadTable .slFromState option:selected').val();
                    objinv.actualFromStateCode = $('#HeadTable .slFromStateAct option:selected').val();
                    objinv.isComp = $("#hdnfrmCom").val();
                    objinv.toType = toType;
