                    objinv.cessValue = parseFloat($("#txtCess").val());
                    objinv.cgstValue = parseFloat($("#txtCGST").val());
                    objinv.sgstValue = parseFloat($("#txtSGST").val());
                    objinv.igstValue = parseFloat($("#txtIGST").val());
                    objinv.OthValue = parseFloat($("#txtOth").val() ? $("#txtOth").val() : 0);
                    objinv.TotNonAdvolVal = parseFloat($("#txtnNonAdvol").val() ? $("#txtnNonAdvol").val() : 0);
                    objinv.totInvValue = parseFloat($("#txtTotInvVal").val());
                    if (objinv.fromPincode.length != 6) {
                        $.alert("Invalid Dispatch from PIN Code");
                        $('#btnsbmt').prop('disabled', false);
                        return false;
                    }
                    if (objinv.toPincode.length != 6) {
                        $.alert("Invalid Ship to PIN Code");
                        $('#btnsbmt').prop('disabled', false);
                        return false;
                    }
                    var TotAll = parseFloat(objinv.totalValue) +
                                 objinv.sgstValue + objinv.cgstValue + objinv.igstValue +
                                 objinv.cessValue + objinv.TotNonAdvolVal + objinv.OthValue;
                    if (TotAll < 0) {
                        $.alert("Tot.Taxble Val+SGST+CGST+IGST+Cess+Cess Non Advol+Other Amount Should not be lesser than 0");
                        $('#btnsbmt').prop('disabled', false);
                        return false;
                    }

                    else if (TotAll - objinv.totInvValue > 2) {
                        $.alert("Tot.Taxble Val+SGST+CGST+IGST+Cess+Cess Non Advol+Other Amount Should not be more than Total Inv.Value");
                        $('#btnsbmt').prop('disabled', false);
                        return false;
                    }
                    else if (TotAll - objinv.totInvValue < -2) {
                        var isConfirm = confirm('Alert! Tot.Taxble Val+SGST+CGST+IGST+Cess+Cess Non Advol+Other Amount  is less than Total Inv. Value');
                        if (!isConfirm) {
                            $('#btnsbmt').prop('disabled', false);
                            return false;
                        }
                    }
                    if (!CheckTransTypeState(objinv.transType, objinv.fromStateCode, objinv.actualFromStateCode, objinv.toStateCode, objinv.actualToStateCode, objinv.subSupplyType)) {
                        $('#btnsbmt').prop('disabled', false);
                        return false;
                    }
                    if ($("#hdnfrmCom").val() == "Y" && objinv.fromStateCode != objinv.toStateCode
                        && objinv.subSupplyType != 4 && objinv.subSupplyType != 6 && objinv.subSupplyType != 7 && objinv.subSupplyType != 8) {

                        $.alert("Sorry your supplier is composition tax payer, you are not allowed for interstate transaction");
                        $('#btnsbmt').prop('disabled', false);
                        return false;
                    }
                    if (($.trim($('.txtDistance').val()) != '' && parseInt($('.txtDistance').val()) >= 0)) {
                        objinv.transporterId = $('.txtTransid').val();
                        objinv.transporterName = $('.txtTransporter').val();
                        objinv.transDocNo = $(".txtTransDocNo").val();
                        objinv.transDocDate = $(".txtTransDocDt").val();
                        objinv.transMode = $('#HeadTable .rblMode input:checked').val();
                        objinv.transDistance = $('.txtDistance').val();
                        objinv.vehicleNo = $(".txtVehicleNo").val();
