                    objinv.FromSEZGSTN = $('#hdnfrmSez').val();
                    objinv.ToSEZGSTN = $('#hdntoSez').val();
                    var isDisabled = $('#tblProducts .SelectCSGST').prop('disabled');

                    if (isDisabled) {
                        objinv.taxType = "IG";
                    }
                    else {
                        objinv.taxType = "SC";
                    }

                    if (objinv.totInvValue > 100000000) {
                        var isConfirm = confirm('Total Inv. Value is more than 10 Crore.');
