                    }

                    var Continue = false;

                    var isConfirmDoc = confirm("Alert..! if Document No. is Prefixed with 0 or / or - characters,it will be removed. Do you want to continue with generation of e-way bill ?");
                    if (!isConfirmDoc) {
                        $('#btnsbmt').prop('disabled', false);
