                                        data: "{ewayBill:" + JSON.stringify(objinv) + "}",
                                        contentType: 'application/json; charset=utf-8',
                                        dataType: 'json',
                                        beforeSend: function (xhr) {
                                            xhr.setRequestHeader("STicket", $("#mytoken").val());
                                        },
                                        success: function (r) {
                                            if (r.d.indexOf('Error') == -1) {
                                                var res = r.d.split('@');
                                                window.location.href = "../eway-simulation/print-bill?ewb_no=" + res[0] + "&cal=1";
                                            }
                                            else {
                                                $('#btnsbmt').prop('disabled', false);
                                                $.alert(r.d)
                                                if (r.d.indexOf('Session') >= 0) {
                                                    window.location.replace("../login.aspx");
                                                }
                                            };
                                        },
                                        error: function (data, status, error) {
                                            $('#btnsbmt').prop('disabled', false);
                                            $.alert(data.responseText);
                                        }
                                    });
                                }
                                else {
                                    if (confirm(r.d)) {
                                        Continue = true;
                                        $.ajax({
                                            type: "POST",
                                            url: '../eway-simulation/save-bill-details',
                                            data: "{ewayBill:" + JSON.stringify(objinv) + "}",
                                            contentType: 'application/json; charset=utf-8',
                                            dataType: 'json',
                                            beforeSend: function (xhr) {
                                                xhr.setRequestHeader("STicket", $("#mytoken").val());
                                            },
                                            success: function (r) {
                                                if (r.d.indexOf('Error') == -1) {
                                                    var res = r.d.split('@');
                                                    window.location.href = "../eway-simulation/print-bill?ewb_no=" + res[0] + "&cal=1";
                                                }
                                                else {
                                                    $('#btnsbmt').prop('disabled', false);

                                                    $.alert(r.d)
                                                    if (r.d.indexOf('Session') >= 0) {
                                                        window.location.replace("../login.aspx");
                                                    }
                                                };
                                            },
                                            error: function (data, status, error) {
                                                $('#btnsbmt').prop('disabled', false);
                                                $.alert(data.responseText);
                                            }
                                        });
                                    }
                                    else {
                                        $('hdnConfirm').val('N');
                                        $('#btnsbmt').prop('disabled', false);
                                        Continue = false;
                                    }

                                }

                            }
                            else {
                                $('#btnsbmt').prop('disabled', false);
                                $.alert(r.d)
                                Continue = false;
                                if (r.d.indexOf('Session') >= 0) {
                                    window.location.replace("../login.aspx");
                                }
                            };
                        },
                        error: function (data, status, error) {

                            $('#btnsbmt').prop('disabled', false);
                            $.alert(data.responseText);
                            Continue = false;
                        }
                    });
                }
            });


        });
        function GetDistance() {
            var PINTOPIN = 'Y';
            if (PINTOPIN == "Y") {
                var pinCode1 = $('.txtFromPincode').val();
                var pinCode2 = $('.txtToPincode').val();
                if ($.trim(pinCode1) != '' && $.trim(pinCode2) != '') {
                    if ($.trim(pinCode1).length == 6 && $.trim(pinCode2).length == 6) {
                        var PinList = pinCode1 + "," + pinCode2;
                        var checktype = "0";
                        if ($('#ctl00_ContentPlaceHolder1_rbtOutwardInward input:checked').val() == "O") {
                            checktype = $('#ctl00_ContentPlaceHolder1_rbtOutSubType input:checked').val();
                        }
                        $.ajax({
                            type: "POST",
                            contentType: 'application/json; charset=utf-8',
                            url: '../eway-simulation/get-auto-distance',
                            data: JSON.stringify({ PinLst: PinList }),
                            dataType: "json",
                            beforeSend: function (xhr) {
                                xhr.setRequestHeader("STicket", $("#mytoken").val());
                            },
                            success: function (data) {
                                $("#hdnDist").val(data.d);
                                var DistAuto = 'Y';
                                if (DistAuto == "Y") {
                                    if (data.d != "" && data.d != "0") {
                                        var dist = Math.round(data.d);
                                        if (checktype == "10" && $.trim(pinCode1) == $.trim(pinCode2)) {
                                            $('#lblDistance').text("300");
                                        }
                                        else {
                                            $('#lblDistance').text(dist);
                                        }
                                        $('.txtDistance').val(dist);
                                    }
                                    else {

                                        $('#lblDistance').text("Not Available");
                                        $('.txtDistance').val('');
                                    }
                                }
                            },
                            error: function (data, status, error) {
                            }
                        });
                    }

                }
            }
        }
