        function storeTblValues() {
            var TableData = new Array();
            $('#tblProducts tr').each(function (row, tr) {
                if ($(tr).find('td:eq(2) input').val() !== undefined && $(tr).find('td:eq(2) input').val() != "") {
                    TableData[row] = {
                        "productId": $(tr).find('td:eq(10) input.hdnProductId[type="hidden"]').val() ? $(tr).find('td:eq(10) input.hdnProductId[type="hidden"]').val() : 0
                        , "productName": $(tr).find('td:eq(0) input').val()
                        , "productDesc": $(tr).find('td:eq(1) input').val()
                        , "hsnCode": $(tr).find('td:eq(2) input').val()
                        , "quantity": parseFloat($(tr).find('td:eq(3) input').val() ? $(tr).find('td:eq(3) input').val() : 0)
                        , "qtyUnit": $(tr).find('td:eq(4) input').val()
                        , "taxableAmount": parseFloat($(tr).find('td:eq(5) input').val())
                        , "cgstRate": parseFloat($(tr).find('.SelectCSGST').val() ? $(tr).find('.SelectCSGST').val() : -1)
                        , "sgstRate": parseFloat($(tr).find('.SelectCSGST').val() ? $(tr).find('.SelectCSGST').val() : -1)
                        , "igstRate": parseFloat($(tr).find('.SelectIGST').val() ? $(tr).find('.SelectIGST').val() : -1)
                        , "cessRate": parseFloat(($(tr).find('.SelectCESS').val()) ? $(tr).find('.SelectCESS').val() : -1)
                        , "cessNonAdvol": parseFloat(($(tr).find('.SelectCNonAdvol').val()) ? $(tr).find('.SelectCNonAdvol').val() : -1)

                    }
                }

            });
            TableData.shift();
            return TableData;
        }
        function EnableDocsType(TransType, SupplyType) {
            $.ajax({
                type: "POST",
                contentType: "application/json; charset=utf-8",
                url: "../eway-simulation/get-doc-type",
                data: "{'Supplytype':'" + TransType + "','SubSupplyType':'" + SupplyType + "'}",
                dataType: "json",
                success: function (Supdata) {
                    var docType = Supdata.d.map(function (obj) { return obj.DocType; });
                    docType = docType.filter(function (v, i) { return docType.indexOf(v) == i; });
                    var ToGstinType = Supdata.d.map(function (obj) { return obj.ToGstin; });
                    ToGstinType = ToGstinType.filter(function (v, i) { return ToGstinType.indexOf(v) == i; });
                    var FromGstinType = Supdata.d.map(function (obj) { return obj.FromGstin; });
                    FromGstinType = FromGstinType.filter(function (v, i) { return FromGstinType.indexOf(v) == i; });
                    for (var i = 0; i < Supdata.d.length; i++) {
                        if (i == 0) {
                            $("#ddlDocType").val(Supdata.d[i].DocType);
                            $("#ddlDocType").children('option').hide();
                        }
                        $("#ddlDocType").children("option[value=" + Supdata.d[i].DocType + "]").show();
                    }
                    if ($("#hdnfrmCom").val() == "Y") {
                        $("#ddlDocType option[value='INV']").remove();
                    }
                    if (docType.length == 1) {
                        $("#ddlDocType").prop("disabled", true);
                    }
                    else {
                        $("#ddlDocType").removeAttr('disabled');
                    }
                    if (TransType == "O") {
                        var isDisabled = $(".txtFromGSTIN").prop('readonly');
                        if ($.trim($(".txtFromGSTIN").val()).toUpperCase() == "URP" && isDisabled) {
                            ClearFromInfo();
                        }
                        if (ToGstinType.length == 1) {
                            if (ToGstinType[0] == "SLF") {
                                var cnt = 0;
