        function CheckTransTypeState(TransType, FromState, ActFromState, ToState, ActToState, SubSupplyType) {
            var TransStateCheck = true;
            var IsFrmsez = $('#hdnfrmSez').val();
            var IsTosez = $('#hdntoSez').val();
            if (SubSupplyType == 2 && $.trim($(".txtFromGSTIN").val().toUpperCase()) == "URP" && FromState == 99) {
                IsFrmsez = "Y";
            }
            if (SubSupplyType == 3 && $.trim($(".txtToGSTIN").val().toUpperCase()) == "URP" && ToState == 99) {
                IsTosez = "Y";
            }
            if (TransType != "1" && TransType != "2" && TransType != "3" && TransType != "4") {
                TransStateCheck = false;
                $.alert("Invalid Transaction Type");
                $('#btnsbmt').prop('disabled', false);
                return false;
            }
            else if (TransType == "1") {
                if ((FromState != ActFromState && IsFrmsez != 'Y') &&
                    (ToState != ActToState && IsTosez != 'Y')) {
                    TransStateCheck = false;
                    $.alert("for Regular Trans. type Bill from state & Dispatch from state,Bill to state & ship to State should be same ");
                    $('#btnsbmt').prop('disabled', false);
                    return false;
                }

                if (FromState != ActFromState) {
                    if (IsFrmsez == 'Y' && FromState == 99) {
                    }
                    else {
                        TransStateCheck = false;
                        $.alert("for Regular Trans. type Bill from state & Dispatch from state should be same ");
                        $('#btnsbmt').prop('disabled', false);
                        return false;
                    }
                }
                if (ToState != ActToState) {
                    if (IsTosez == 'Y' && ToState == 99) {
                    }
                    else {
                        TransStateCheck = false;
                        $.alert("for Regular Trans. type Bill to state & ship to State should be same ");
                        $('#btnsbmt').prop('disabled', false);
                        return false;
                    }
                }
            }
            else if (TransType == "2") {
                if (FromState != ActFromState) {
                    if (IsFrmsez == 'Y' && FromState == 99) {
                    }
                    else {
                        TransStateCheck = false;
                        $.alert("for Bill To - Ship To Trans.type Bill from state & Dispatch from state should be same ");
                        $('#btnsbmt').prop('disabled', false);
                        return false;
                    }
                }
            }
            else if (TransType == "3") {
                if (ToState != ActToState) {
                    if (IsTosez == 'Y' && ToState == 99) {
                    }
                    else {
                        TransStateCheck = false;
                        $.alert("for Bill From - Dispatch From Trans. type Bill to state & ship to State should be same ");
                        $('#btnsbmt').prop('disabled', false);
                        return false;
                    }
                }

            }
            return TransStateCheck;
        }
