            var igstVal = 0;
            var cessVal = 0;
            if ($.isNumeric($("#txtCGST").val())) {
                cgstVal = parseFloat($("#txtCGST").val());
            }
            if ($.isNumeric($("#txtSGST").val())) {
                sgstVal = parseFloat($("#txtSGST").val());
            }
            if ($.isNumeric($("#txtIGST").val())) {
                igstVal = parseFloat($("#txtIGST").val());
            }
            if ($.isNumeric($("#txtCess").val())) {
                cessVal = parseFloat($("#txtCess").val());
            }
            if ($.isNumeric($("#txtTotbasicval").val())) {
