        function calculateSum() {
            var CalcTtlSum = 0;
            var cgstVal = 0;
            var sgstVal = 0;
            var igstVal = 0;
            var cessVal = 0;
            var totinvval = 0;
            $("#Tbl_products .txttot").each(function () {
                var txttot_sum = $(this).val();
                var rowid = $(this);
                if ($.isNumeric(txttot_sum)) {
                    CalcTtlSum += parseFloat(txttot_sum);
                    var cgstRate = rowid.closest('tr').find('.SelectCSGST').val();
                    if ($.isNumeric(cgstRate)) {
                        if (cgstRate >= 0)
                            cgstVal += parseFloat(txttot_sum) * parseFloat(cgstRate) / 100;
                    }
                    var sgstRate = rowid.closest('tr').find('.SelectCSGST').val();
                    if ($.isNumeric(sgstRate)) {
                        if (sgstRate >= 0)
                            sgstVal += parseFloat(txttot_sum) * parseFloat(sgstRate) / 100;
                    }
                    var igstRate = rowid.closest('tr').find('.SelectIGST').val();
                    if ($.isNumeric(igstRate)) {
                        if (igstRate >= 0)
                            igstVal += parseFloat(txttot_sum) * parseFloat(igstRate) / 100;
                    }
                    var cess = rowid.closest('tr').find('.SelectCESS').val();
                    if ($.isNumeric(cess)) {
                        if (cess >= 0)
                            cessVal += parseFloat(txttot_sum) * parseFloat(cess) / 100;
                    }

                    var OthVal = parseFloat($("#txtOth").val() ? $("#txtOth").val() : 0);
                    var CessNonAdvol = parseFloat($("#txtnNonAdvol").val() ? $("#txtnNonAdvol").val() : 0);

                    totinvval = CalcTtlSum + cgstVal + sgstVal + igstVal + cessVal + OthVal + CessNonAdvol;
                }

            });
            $("#txtTotbasicval").val(CalcTtlSum.toFixed(2));
            $("#txtCGST").val(cgstVal.toFixed(2));
            $("#txtSGST").val(sgstVal.toFixed(2));
            $("#txtIGST").val(igstVal.toFixed(2));
            $("#txtCess").val(cessVal.toFixed(2));
            $("#txtTotInvVal").val(totinvval.toFixed(2));
        }
