        function calculateTax() {

            var cgst_sum = 0;
            jQuery("#Tbl_products .hdnCgst").each(function () {
                var txtcg = $(this).val();
                if ($.isNumeric(txtcg)) {
                    cgst_sum += parseFloat(txtcg);
                }
            });
            $("#txtCGST").val(cgst_sum.toFixed(2));

            var sgst_sum = 0;
            jQuery("#Tbl_products .hdnSgst").each(function () {
                var txtsg = $(this).val();
                if ($.isNumeric(txtsg)) {
                    sgst_sum += parseFloat(txtsg);
                }
            });
            $("#txtSGST").val(sgst_sum.toFixed(2));

            var igst_sum = 0;
            jQuery("#Tbl_products .hdnIgst").each(function () {
                var txtig = $(this).val();
                if ($.isNumeric(txtig)) {
                    igst_sum += parseFloat(txtig);
                }
            });
            $("#txtIGST").val(igst_sum.toFixed(2));

            var cess_sum = 0;
            jQuery("#Tbl_products .hdnCess").each(function () {
                var txtcess = $(this).val();
                if ($.isNumeric(txtcess)) {
                    cess_sum += parseFloat(txtcess);
                }
            });
            var cess_advol_sum = 0;
            jQuery("#Tbl_products .hdnCessAdvol").each(function () {
                var txtcessadvol = $(this).val();
                if ($.isNumeric(txtcessadvol)) {
                    cess_advol_sum += parseFloat(txtcessadvol);
                }
            });
            $("#txtCess").val((parseFloat(cess_sum) + parseFloat(cess_advol_sum)).toFixed(2));
        }
