        function validateVehicle(oSrc, args) {
            var pattern1 = /^[A-Z a-z]{2}[0-9]{2}[A-Z a-z]{0,2}[0-9]{4}$/;
            var pattern2 = /^[A-Z a-z]{3}[0-9]{4}$/;
            var pattern3 = /^[A-Z a-z]{2}[0-9]{3}[A-Z a-z]{1}[0-9]{4}$/;
            var pattern4 = /^[A-Z a-z]{2}[0-9]{2}[A-Z a-z]{3}[0-9]{4}$/;
            if (args.Value.length >= 5) {
                // DF-Defense , TM as Temporary.
                if (args.Value.substring(0, 2).toUpperCase() != "DF" && args.Value.substring(0, 2).toUpperCase() != "TM" && args.Value.substring(0, 2).toUpperCase() != "BP" && args.Value.substring(0, 2).toUpperCase() != "NP") {
                    if (pattern1.test(args.Value) || pattern3.test(args.Value) || pattern4.test(args.Value)) {
                        var vehStateCodeStr = args.Value.substring(0, 2);
                        if (!validateVehicleStateCode(vehStateCodeStr.toUpperCase())) {
                            $.alert("First 2 characters of Vehicle No. does not indicate any state, so please enter a valid vehicle number");
                            args.IsValid = false;
                            $(".txtVehicleNo").val('');
                        }
                        args.IsValid = true;
                    }
                    else if (pattern2.test(args.Value)) {
                        args.IsValid = true;
                    }
                    else {
                        args.IsValid = false;
                    }
                }
                if (args.IsValid == true) {
                    //  document.getElementById("Div_vehclassnote").setAttribute("hidden", "");
                    vehiclecheck();

                }
                else {
                    // debugger;
                    document.getElementById("Div_vehclass").setAttribute("hidden", "");
                    if (args.Value.substring(0, 2).toUpperCase() == "TR") {
                        //  document.getElementById("Div_vehclassnote").removeAttribute("hidden");
                    }
                    else {
                        // document.getElementById("Div_vehclassnote").setAttribute("hidden", "");
                    }

                }
            }
            else {
                $(".txtVehicleNo").val('');
                $.alert("Please enter a valid Vehicle number");
            }
        }

        function vehiclecheck() {
            value = $(".txtVehicleNo").val();
            document.getElementById("Div_vehclass").setAttribute("hidden", "");
            $.ajax({

                type: "POST",
                contentType: "application/json; charset=utf-8",
                url: "../eway-simulation/get-vehicle-details",
                data: "{'ewbVehno':'" + value + "'}",
                dataType: "json",
                success: function (msg) {
                    if (msg.d == "0") {
                        var label = $("#hdnalrt").val();
                        document.getElementById("Div_vehclass").setAttribute("hidden", "");
                        ConfirmDialog(label);

                    }
                    else if (msg.d == "1") {
                        document.getElementById("Div_vehclass").setAttribute("hidden", "");

                    }
                    else {

                        if (msg.d != "") {
                            var stng = msg.d;
                            if (stng.indexOf("more") >= 0) {
                                document.getElementById("Div_vehclass").removeAttribute("hidden");
                                $('#ctl00_ContentPlaceHolder1_lbl_vehclass').html(msg.d);

                            }
