    <script type="text/javascript">
        function ValidateDecimal(el) {
            var rateact = el.value;
            var rgexp = /^\d{1,2}(?:[.]\d{1,3})?$/;
            if (!rgexp.test(rateact)) {
                el.value = '';
                alert("Invalid Rates");
            }
        }
    </script>
